import { mock } from 'bun:test';
import assert from 'node:assert/strict';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { MemoryRouter } from 'react-router-dom';

const settings: any = { version: 1, themes: { dark: { targets: { desktop: { pages: {} } } } } };
mock.module('../../src/hooks/ui/useCustomization', () => ({ useCustomization: () => ({ settings, userId: null, syncStatus: 'saved', savePatch: async () => {} }), useCustomizationScope: () => ({ themeId: 'dark', target: 'desktop' }) }));
mock.module('../../src/hooks/ui/useUiTranslation', () => ({ useUiTranslation: () => {} }));
mock.module('../../src/components/settings/BackgroundEditor', () => ({ AppearanceBackground: ({ background }: any) => background ? <i data-background-layer="true" /> : null, BackgroundEditor: () => null, AppearanceDraftProvider: ({ children }: any) => <>{children}</> }));
mock.module('../../src/components/media/MediaLibraryMenu', () => ({ MediaLibraryMenu: ({ children }: any) => <>{children}</>, LibraryMenuButton: () => { throw Error('A preview must not mount mutating library controls'); }, LIBRARY_BUTTON_CLASS: 'media-library-glass' }));
mock.module('../../src/components/customization/CustomShelf', () => ({ SavedCustomShelf: () => <section>Custom shelf</section> }));
mock.module('../../src/components/customization/CustomShelfEditor', () => ({ CustomShelfEditor: () => <div>Source editor</div> }));

const { MediaCardFrame } = await import('../../src/components/MediaCardFrame');
const { CardDesignPreviewProvider } = await import('../../src/components/customization/CardDesignContext');
const { HomeCustomization } = await import('../../src/components/customization/HomeCustomization');
const { useSpotlightPresentation } = await import('../../src/components/customization/SpotlightPresentation');
function SpotlightProbe() { const value = useSpotlightPresentation(); return <section data-shared-variant={value?.variant || 'default'} data-shared-height={value?.height} />; }
const frame = <MediaCardFrame title="Example title" href="/anime/42" poster={<img src="/poster.png" alt="" />} metadata={<span>12 episodes</span>} />;
const ordinary = renderToStaticMarkup(<MemoryRouter><CardDesignPreviewProvider design={null} readOnly={false}>{frame}</CardDesignPreviewProvider></MemoryRouter>);
assert(ordinary.includes('data-card-style="overlay"'));
assert(ordinary.includes('class="media-card-poster relative aspect-[2/3] overflow-hidden rounded-2xl border border-border bg-muted"'));
assert(ordinary.includes('href="/anime/42"'));
assert(!ordinary.includes('data-custom-card'));

const design: any = { id: 'mine', name: 'My design', base: 'overlay', slots: { title: { zone: 'top-center', order: 0, visible: true }, rating: { zone: 'bottom-right', order: 0, visible: true }, status: { zone: 'below', order: 1, visible: false }, menu: { zone: 'top-right', order: 0, visible: true } }, style: { width: 192, radius: 23, titleSize: 21, aspectRatio: 'square', background: { type: 'solid', color: '#123456' } } };
const preview = renderToStaticMarkup(<MemoryRouter><CardDesignPreviewProvider design={design}><MediaCardFrame title="Example title" href="/anime/42" libraryItem={{ kind: 'anime', id: '42', name: 'Example title' }} poster={<img src="/poster.png" alt="" />} slotContent={{ title: 'Example title', rating: '9.1', status: 'Secret status' }} safetyBadges={<strong>18+</strong>} /></CardDesignPreviewProvider></MemoryRouter>);
assert(preview.includes('data-card-zone="top-center"'));
assert(preview.includes('data-card-zone="bottom-right"'));
assert(preview.includes('border-radius:23px'));
assert(preview.includes('aspect-ratio:1'));
assert(preview.includes('max-width:192px'));
assert(preview.indexOf('data-background-layer') < preview.indexOf('data-mobile-poster-image'));
assert(preview.includes('18+'));
assert(preview.includes('media-library-glass'));
assert(!preview.includes('Secret status'));
assert(!preview.includes('href='));
assert(!preview.includes('<button'));

let mounted = 0;
function QuerySection() { mounted++; return <section>Query section</section>; }
const descriptors = [{ id: 'hero', label: 'Hero', node: <section className="original-hero">Hero</section> }, { id: 'query', label: 'Query', collection: true, node: <QuerySection /> }];
const plainHome = renderToStaticMarkup(<MemoryRouter><HomeCustomization pageId="anime-home" sections={descriptors} /></MemoryRouter>);
assert.equal(mounted, 1);
assert(plainHome.includes('<section class="original-hero">Hero</section><section>Query section</section>'));
assert(!plainHome.includes('home-custom-section'));
settings.themes.dark.targets.desktop.pages['anime-home'] = { sections: { query: { visible: false } } };
mounted = 0;
const hiddenHome = renderToStaticMarkup(<MemoryRouter><HomeCustomization pageId="anime-home" sections={descriptors} /></MemoryRouter>);
assert.equal(mounted, 0);
assert(!hiddenHome.includes('Query section'));
const editHome = renderToStaticMarkup(<MemoryRouter initialEntries={['/?customize=1']}><HomeCustomization pageId="anime-home" sections={descriptors} /></MemoryRouter>);
assert(editHome.includes('Home customization controls'));
assert(editHome.includes('Hidden section'));
assert(editHome.includes('Move Hero down'));
assert(editHome.includes('Preview'));
assert(editHome.includes('Settings for Hero'));
assert(!editHome.includes('Section layout'));
assert(!editHome.includes('original-hero'));
settings.themes.dark.targets.desktop.designs = { chosen: design };
settings.themes.dark.targets.desktop.activeDesign = 'chosen';
const chosenCard = renderToStaticMarkup(<MemoryRouter>{frame}</MemoryRouter>);
assert(chosenCard.includes('data-custom-card="mine"'));
settings.themes.dark.targets.desktop.pages['card-home'] = { sections: { card: { designId: 'removed-design' } } };
const chosenSection = renderToStaticMarkup(<MemoryRouter><HomeCustomization pageId="card-home" sections={[{ id: 'card', label: 'Card', node: frame }]} /></MemoryRouter>);
assert(chosenSection.includes('data-custom-card="mine"'));
settings.themes.dark.targets.desktop.pages['trending-home'] = { sections: { trending: { designId: 'chosen', layout: 'grid', background: { type: 'solid', color: '#f00' } } } };
const preservedTrending = renderToStaticMarkup(<MemoryRouter><HomeCustomization pageId="trending-home" sections={[{ id: 'trending', label: 'Trending', node: frame, collection: true, layoutLocked: 'original', preservePresentation: true }]} /></MemoryRouter>);
assert(!preservedTrending.includes('data-custom-card'));
assert(!preservedTrending.includes('home-custom-section'));
assert(preservedTrending.includes('data-card-style="overlay"'));
settings.themes.dark.targets.desktop.spotlight = { variant: 'classic', height: 480 };
settings.themes.dark.targets.desktop.pages['shared-home'] = { sections: { spotlight: { spotlight: { variant: 'cinematic', height: 900 } } } };
const sharedHome = renderToStaticMarkup(<MemoryRouter><HomeCustomization pageId="shared-home" sections={[{ id: 'spotlight', label: 'Spotlight', node: <SpotlightProbe /> }]} /></MemoryRouter>);
assert(sharedHome.includes('data-shared-variant="classic"'));
assert(sharedHome.includes('data-shared-height="480"'));
const providerDefault = renderToStaticMarkup(<MemoryRouter><HomeCustomization pageId="provider-default" sections={[{ id: 'spotlight', label: 'Spotlight', node: <SpotlightProbe /> }]} defaultContent={<SpotlightProbe />} /></MemoryRouter>);
assert(providerDefault.includes('data-shared-variant="classic"'));
settings.themes.dark.targets.desktop.spotlight = { variant: 'default' };
const resetGlobal = renderToStaticMarkup(<MemoryRouter><HomeCustomization pageId="shared-home" sections={[{ id: 'spotlight', label: 'Spotlight', node: <SpotlightProbe /> }]} /></MemoryRouter>);
assert(resetGlobal.includes('data-shared-variant="default"'));
assert(!resetGlobal.includes('data-shared-height'));
console.log('customization render checks passed');
